def longest_even_vowel_substring(s):
 bit={'a':1,'e':2,'i':4,'o':8,'u':16};first={0:-1};mask=answer=0
 for i,char in enumerate(s):
  mask^=bit.get(char,0)
  if mask in first:answer=max(answer,i-first[mask])
  else:first[mask]=i
 return answer

